        { blst_sk_to_pk_in_g2(_point, sk.Key); }

        public P2(scoped ReadOnlySpan<byte> inp) : this()
            => Decode(inp);

        public P2(P2Affine affine) : this()
        { blst_p2_from_affine(_point, affine.Point); }

        public readonly void Zero()
            => _point.Clear();

        /// <summary>
        /// Decodes a 96-byte compressed or 192-byte uncompressed point.
        /// Unlike <see cref="P2Affine.TryDecode"/>, the uncompressed path reads the four field
        /// elements as-is with no validation (no canonicality, flag-bit, curve or subgroup checks),
        /// so that callers implementing protocols such as EIP-2537 can validate separately.
        /// Call <see cref="OnCurve"/>/<see cref="InGroup"/> where validation is required.
        /// </summary>
        public bool TryDecode(scoped ReadOnlySpan<byte> inp, out ERROR err)
        {
            int len = inp.Length;
            if (len == 0 || len != ((inp[0] & 0x80) == 0x80 ? P2_COMPRESSED_SZ
                                                          : 2 * P2_COMPRESSED_SZ))
            {
                err = ERROR.BADENCODING;
                return false;
            }

            if (len == 2 * P2_COMPRESSED_SZ)
            {
                blst_fp_from_bendian(_point, inp[48..]);
                blst_fp_from_bendian(_point[6..], inp[..48]);
                blst_fp_from_bendian(_point[12..], inp[144..]);
                blst_fp_from_bendian(_point[18..], inp[96..]);
            }
            else
            {
                err = blst_p2_deserialize(_point, inp);
                if (err != ERROR.SUCCESS)
                {
                    return false;
                }
            }

            blst_p2_from_affine(_point, _point);

            err = ERROR.SUCCESS;
            return true;
        }

        /// <summary>Decodes raw affine coordinates without any validation, as in <see cref="TryDecode"/>.</summary>
        public void Decode(ReadOnlySpan<byte> fp1, ReadOnlySpan<byte> fp2, ReadOnlySpan<byte> fp3, ReadOnlySpan<byte> fp4)
        {
            if (fp1.Length != 48 || fp2.Length != 48 || fp3.Length != 48 || fp4.Length != 48)
            {
                throw new ArgumentException("Invalid input length. Expected 48 bytes for each field element.");
            }

            blst_fp_from_bendian(_point, fp1);
            blst_fp_from_bendian(_point[6..], fp2);
            blst_fp_from_bendian(_point[12..], fp3);
            blst_fp_from_bendian(_point[18..], fp4);
            blst_p2_from_affine(_point, _point);
        }

        public void Decode(scoped ReadOnlySpan<byte> inp)
        {
            if (!TryDecode(inp, out ERROR err))
            {
                throw new BlsException(err);
            }
        }

        public readonly P2 Dup() => new(this);
        public readonly P2Affine ToAffine() => new(this);
        public readonly byte[] Serialize()
        {
            byte[] ret = new byte[2 * P2_COMPRESSED_SZ];
            blst_p2_serialize(ret, _point);
            return ret;
        }
        public readonly byte[] Compress()
        {
            byte[] ret = new byte[P2_COMPRESSED_SZ];
            blst_p2_compress(ret, _point);
            return ret;
        }

        public readonly bool OnCurve()
            => blst_p2_on_curve(_point);
        public readonly bool InGroup()
            => blst_p2_in_g2(_point);
        public readonly bool IsInf()
            => blst_p2_is_inf(_point);
        public readonly bool IsEqual(P2 p)
            => blst_p2_is_equal(_point, p._point);

        public readonly P2 MapTo(scoped ReadOnlySpan<byte> c0, scoped ReadOnlySpan<byte> c1)
        {
            if (c0.Length != 48 || c1.Length != 48)
            {
                throw new ArgumentException("Invalid input length. Expected 48 bytes for each field element.");
            }

            Span<long> u = stackalloc long[12];
            blst_fp_from_bendian(u, c0);
            blst_fp_from_bendian(u[6..], c1);
            blst_map_to_g2(_point, u, default);
            return this;
        }
        public readonly P2 HashTo(scoped ReadOnlySpan<byte> msg, scoped ReadOnlySpan<byte> DST = default, scoped ReadOnlySpan<byte> aug = default)
        {
            blst_hash_to_g2(_point, msg, (size_t)msg.Length,
                                    DST, (size_t)DST.Length,
                                    aug, (size_t)(!aug.IsEmpty ? aug.Length : 0));
            return this;
        }
        public readonly P2 EncodeTo(scoped ReadOnlySpan<byte> msg, scoped ReadOnlySpan<byte> DST = default, scoped ReadOnlySpan<byte> aug = default)
        {
            blst_encode_to_g2(_point, msg, (size_t)msg.Length,
                                      DST, (size_t)DST.Length,
                                      aug, (size_t)(!aug.IsEmpty ? aug.Length : 0));
            return this;
        }

        public readonly P2 SignWith(SecretKey sk)
        { blst_sign_pk_in_g1(_point, _point, sk.Key); return this; }
        public readonly P2 SignWith(Scalar scalar)
        { blst_sign_pk_in_g1(_point, _point, scalar.Val); return this; }

        public readonly void Aggregate(P2Affine inp)
        {
            if (blst_p2_affine_in_g2(inp.Point))
            {
                blst_p2_add_or_double_affine(_point, _point, inp.Point);
            }
            else
            {
                throw new BlsException(ERROR.POINTNOTINGROUP);
            }
        }

        public readonly P2 Mult(scoped ReadOnlySpan<byte> scalar)
        {
            blst_p2_mult(_point, _point, scalar, (size_t)(scalar.Length * 8));
            return this;
        }
        public readonly P2 Mult(Scalar scalar)
        {
            blst_p2_mult(_point, _point, scalar.Val, 255);
            return this;
        }
        public readonly P2 Mult(in BigInteger scalar)
        {
            byte[] val;
            if (scalar.Sign < 0)
            {
                val = BigInteger.Negate(scalar).ToByteArray();
                blst_p2_cneg(_point, true);
            }
            else
            {
                val = scalar.ToByteArray();
            }
            int len = val.Length;
            if (val[len - 1] == 0) len--;
            blst_p2_mult(_point, _point, val, (size_t)(len * 8));
            return this;
        }
        /// <summary>
        /// Multi-scalar multiplication over <paramref name="npoints"/> Jacobian points stored
        /// contiguously in <paramref name="rawPoints"/> with 32-byte little-endian scalars stored
        /// contiguously in <paramref name="rawScalars"/>. Points at infinity must be filtered out
        /// by the caller.
        /// </summary>
        public readonly unsafe P2 MultiMult(scoped ReadOnlySpan<long> rawPoints, scoped ReadOnlySpan<byte> rawScalars, int npoints)
        {
            ArgumentOutOfRangeException.ThrowIfNegative(npoints);
            if (rawPoints.Length < npoints * Sz)
            {
                throw new ArgumentException($"Insufficient points for the given count. Expected {npoints * Sz} longs.", nameof(rawPoints));
            }
            if (rawScalars.Length < npoints * 32)
            {
                throw new ArgumentException($"Insufficient scalars for the given count. Expected {npoints * 32} bytes.", nameof(rawScalars));
            }

            // blst does not support an empty multiplication; the result is the point at infinity
            if (npoints == 0)
            {
                Zero();
                return this;
            }

            int affinesLen = npoints * P2Affine.Sz;
            long[] affines = ArrayPool<long>.Shared.Rent(affinesLen);

            try
            {
                // a [ptr, null] argument tells blst to read all points from one contiguous buffer
                fixed (long* rawPointsPtr = rawPoints)
                {
                    long** points = stackalloc long*[2] { rawPointsPtr, null };
                    blst_p2s_to_affine(affines.AsSpan(0, affinesLen), points, (size_t)npoints);
                }

                return MultiMultAffine(affines.AsSpan(0, affinesLen), rawScalars, npoints);
            }
            finally
            {
                ArrayPool<long>.Shared.Return(affines);
            }
        }

        /// <summary>
        /// As <see cref="MultiMult"/>, but over affine points, skipping the Jacobian-to-affine
        /// batch conversion.
        /// </summary>
        public readonly unsafe P2 MultiMultAffine(scoped ReadOnlySpan<long> rawAffines, scoped ReadOnlySpan<byte> rawScalars, int npoints)
        {
            ArgumentOutOfRangeException.ThrowIfNegative(npoints);
            if (rawAffines.Length < npoints * P2Affine.Sz)
            {
                throw new ArgumentException($"Insufficient points for the given count. Expected {npoints * P2Affine.Sz} longs.", nameof(rawAffines));
            }
            if (rawScalars.Length < npoints * 32)
            {
                throw new ArgumentException($"Insufficient scalars for the given count. Expected {npoints * 32} bytes.", nameof(rawScalars));
            }

            // blst does not support an empty multiplication; the result is the point at infinity
            if (npoints == 0)
            {
                Zero();
                return this;
            }

            int scratchLen = (int)(blst_p2s_mult_pippenger_scratch_sizeof((size_t)npoints) / sizeof(long));
            long[] scratch = ArrayPool<long>.Shared.Rent(scratchLen);

            try
            {
                fixed (long* affinesPtr = rawAffines)
                fixed (byte* scalarsPtr = rawScalars)
                fixed (long* scratchPtr = scratch)
                {
                    long** points = stackalloc long*[2] { affinesPtr, null };
                    byte** scalars = stackalloc byte*[2] { scalarsPtr, null };
                    blst_p2s_mult_pippenger(_point, points, (size_t)npoints, scalars, 256, scratchPtr);
                }
            }
            finally
            {
                ArrayPool<long>.Shared.Return(scratch);
            }

            return this;
        }
        public readonly P2 Cneg(bool flag) { blst_p2_cneg(_point, flag); return this; }
        public readonly P2 Neg() { blst_p2_cneg(_point, true); return this; }
        public readonly P2 Add(P2 a)
        { blst_p2_add_or_double(_point, _point, a.Point); return this; }
        public readonly P2 Add(P2Affine a)
        { blst_p2_add_or_double_affine(_point, _point, a.Point); return this; }
        public readonly P2 Dbl()
        { blst_p2_double(_point, _point); return this; }

        public static P2 Generator()
        {
            long[] res = new long[Sz];
            return Generator(res);
        }

        public static unsafe P2 Generator(Span<long> p)
        {
            P2 res = new(p);
            new ReadOnlySpan<long>((void*)blst_p2_generator(), Sz).CopyTo(res._point);
            return res;
        }
    }

    public static P2 G2() => P2.Generator();

