    public readonly ref struct PT
    {
        public readonly ReadOnlySpan<long> Fp12 { get => _fp12; }
        public static int Sz { get => _sz; }
        private readonly Span<long> _fp12;
        private static readonly int _sz = (int)blst_fp12_sizeof() / sizeof(long);

        public PT(PT orig)
        {
            _fp12 = new long[Sz];
            orig._fp12.CopyTo(_fp12);
        }

        public PT(Span<long> p)
        {
            if (p.Length < Sz)
            {
                throw new ArgumentException($"Invalid point length. Expected {_sz} longs.");
            }
            _fp12 = p[..Sz];
        }

        public PT()
        {
            _fp12 = new long[Sz];
        }

        public PT(P1Affine p) : this()
        { blst_aggregated_in_g1(_fp12, p.Point); }
        public PT(P1 p) : this()
        { blst_aggregated_in_g1(_fp12, new P1Affine(p).Point); }
        public PT(P2Affine q) : this()
        { blst_aggregated_in_g2(_fp12, q.Point); }
        public PT(P2 q) : this()
        { blst_aggregated_in_g2(_fp12, new P2Affine(q).Point); }
        public PT(P2Affine q, P1Affine p) : this()
            => MillerLoop(q, p);
        public PT(P1Affine p, P2Affine q) : this(q, p) { }
        public PT(P2 q, P1 p) : this()
            => MillerLoop(q, p);
        public PT(P1 p, P2 q) : this(q, p) { }

        public void MillerLoop(P2Affine q, P1Affine p)
        { blst_miller_loop(_fp12, q.Point, p.Point); }
        public void MillerLoop(P2 q, P1 p)
            => MillerLoop(q.ToAffine(), p.ToAffine());
        public readonly PT Dup() => new(this);
        public readonly bool IsOne()
            => blst_fp12_is_one(_fp12);
        public readonly bool IsEqual(PT p)
            => blst_fp12_is_equal(_fp12, p._fp12);
        public readonly PT Sqr() { blst_fp12_sqr(_fp12, _fp12); return this; }
        public readonly PT Mul(PT p) { blst_fp12_mul(_fp12, _fp12, p._fp12); return this; }
        public readonly PT FinalExp() { blst_final_exp(_fp12, _fp12); return this; }
        public readonly bool InGroup()
            => blst_fp12_in_group(_fp12);
        public readonly byte[] ToBendian()
        {
            byte[] ret = new byte[12 * P1_COMPRESSED_SZ];
            blst_bendian_from_fp12(ret, _fp12);
            return ret;
        }

        public static bool FinalVerify(PT gt1, PT gt2)
        { return blst_fp12_finalverify(gt1._fp12, gt2._fp12); }

        public static PT One()
        {
            long[] res = new long[Sz];
            return One(res);
        }

        public static unsafe PT One(Span<long> p)
        {
            PT res = new(p);
            new ReadOnlySpan<long>((void*)blst_fp12_one(), Sz).CopyTo(res._fp12);
            return res;
        }

        public void MillerLoopLines(ReadOnlySpan<long> qlines, P1Affine p)
        { blst_miller_loop_lines(_fp12, qlines, p.Point); }

        /// <summary>
        /// Computes the product of the Miller loops of <paramref name="npairs"/> point pairs in a
        /// single batched pass, sharing the Fp12 squarings across pairs. The points are stored
        /// contiguously as affine points in <paramref name="qAffines"/> and <paramref name="pAffines"/>;
        /// pairs where either point is at infinity must be filtered out by the caller.
        /// Substantially faster than multiplying separate <see cref="MillerLoop(P2Affine, P1Affine)"/>
        /// results when <paramref name="npairs"/> &gt; 1.
        /// </summary>
        public readonly unsafe PT MillerLoopN(scoped ReadOnlySpan<long> qAffines, scoped ReadOnlySpan<long> pAffines, int npairs)
        {
            ArgumentOutOfRangeException.ThrowIfNegative(npairs);
            if (qAffines.Length < npairs * P2Affine.Sz)
            {
                throw new ArgumentException($"Insufficient points for the given count. Expected {npairs * P2Affine.Sz} longs.", nameof(qAffines));
            }
            if (pAffines.Length < npairs * P1Affine.Sz)
            {
                throw new ArgumentException($"Insufficient points for the given count. Expected {npairs * P1Affine.Sz} longs.", nameof(pAffines));
            }

            // blst does not write the output for an empty batch; the empty product is one
            if (npairs == 0)
            {
                One(_fp12);
                return this;
            }

            // a [ptr, null] argument tells blst to read all points from one contiguous buffer
            fixed (long* q = qAffines)
            fixed (long* p = pAffines)
            {
                long** qs = stackalloc long*[2] { q, null };
                long** ps = stackalloc long*[2] { p, null };
                blst_miller_loop_n(_fp12, qs, ps, (size_t)npairs);
            }
            return this;
        }
    }

